const cfg = $input.first().json;
const data = $getWorkflowStaticData('global');
data.usedKeywordPairs ||= [];
const limit = Number(cfg.limits.keywordsPerRun || 4);
const markets = cfg.markets || [];
const niches = cfg.niches || [];
if (!markets.length || !niches.length) throw new Error('Runtime Config must define markets and niches.');
const recent = new Set(data.usedKeywordPairs.slice(-500).map(String));
const seed = Math.floor(Date.now() / 86400000);
const candidates = [];
for (let mi = 0; mi < markets.length; mi++) {
  const market = markets[(mi + seed) % markets.length];
  for (let ni = 0; ni < niches.length; ni++) {
    const niche = niches[(ni + seed) % niches.length];
    const cities = market.cities || [];
    const categories = niche.categories || [];
    if (!cities.length || !categories.length) continue;
    const city = cities[(seed + mi * 3 + ni) % cities.length];
    const category = categories[(seed + mi + ni * 2) % categories.length];
    const keyword = `${category} in ${city}, ${market.country}`;
    const pair = `${market.countryCode}|${city}|${category}`.toLowerCase();
    if (!recent.has(pair)) candidates.push({keyword, city, industry:niche.group, category, country:market.country, countryCode:market.countryCode, locale:market.locale, language:market.language, intent:'customer messaging and lead follow-up', pair});
  }
}
// Deterministic daily rotation avoids an AI failure blocking discovery and guarantees market diversity.
candidates.sort((a,b) => ((a.pair.length + seed) % 17) - ((b.pair.length + seed) % 17));
const chosen=[]; const usedCountries=new Set(); const usedIndustries=new Set();
for (const c of candidates) if (!usedCountries.has(c.countryCode) && !usedIndustries.has(c.industry)) { chosen.push(c); usedCountries.add(c.countryCode); usedIndustries.add(c.industry); if(chosen.length===limit) break; }
for (const c of candidates) if (chosen.length < limit && !chosen.some(x=>x.pair===c.pair)) chosen.push(c);
if (!chosen.length) { data.usedKeywordPairs=[]; throw new Error('All keyword pairs exhausted; history reset. Run again.'); }
data.usedKeywordPairs = [...data.usedKeywordPairs, ...chosen.map(x=>x.pair)].slice(-500);
return chosen.slice(0,limit).map(c=>({json:{...cfg,keyword:c.keyword,keywordCity:c.city,keywordIndustry:c.industry,keywordCategory:c.category,keywordIntent:c.intent,country:c.country,countryCode:c.countryCode,locale:c.locale,language:c.language,keywordStatus:'generated',firstSeen:new Date().toISOString()}}));

