/**
 * Main workflow execution
 * Searches Google Maps, scrapes websites, and extracts emails
 */
async function main() {
    // Get workflow input data
    const items = $input.all();
    const workflowContext = (items && items.length > 0) ? items[0].json : {};

    // Extract search keywords
    let keywords = '';
    if (items && items.length > 0) {
        const item = items[0].json;
        keywords = item.keywords || item.query || item.search || item.keyword || '';
    }

    // Fallback keyword if none provided
    if (!keywords || keywords.trim() === '') {
        throw new Error('No keyword supplied by DeepSeek Keyword Strategy');
    }

    console.log(`🔍 Searching: "${keywords}"`);

    // -------- SEARCH GOOGLE MAPS --------

    let searchResult;
    try {
        searchResult = await this.helpers.request({
            method: 'POST',
            url: `${config.BASE_URL}/api/scrape/search`,
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                query: keywords,
                maxResults: config.maxResults
            }),
            json: true,
            timeout: 60000
        });
    } catch (error) {
        return [{
            json: {
                error: `Search failed: ${error.message}`,
                success: false,
                timestamp: new Date().toISOString()
            }
        }];
    }

    // Handle search errors
    if (!searchResult.success) {
        return [{
            json: {
                error: `Search error: ${searchResult.error}`,
                success: false,
                timestamp: new Date().toISOString()
            }
        }];
    }

    const places = searchResult.data?.results || [];
    console.log(`✅ Found ${places.length} total results`);

    // -------- PROCESS RESULTS --------

    const validResults = [];
    let processedCount = 0;

    for (let i = 0; i < places.length; i++) {
        const place = places[i];
        processedCount++;
        console.log(`📋 ${i+1}/${places.length}: ${place.title}`);

        // Skip invalid entries
        if (!place.title || place.title.includes('Logga in') || place.title.includes('Google Maps')) {
            console.log(`   ⚠️ Skipping invalid entry`);
            continue;
        }

        let primaryEmail = 'N/A';
        let allEmails = [];

        // Check if website exists and is valid
        if (place.website && place.website !== 'N/A' && isValidWebsite(place.website)) {
            console.log(`   🌐 Scraping website: ${place.website}`);

            const websiteData = await scrapeWebsite.call(this, place.website);

            if (websiteData.success && websiteData.emails.length > 0) {
                allEmails = websiteData.emails;

                // Prefer business emails over generic providers
                const businessEmails = allEmails.filter(email => {
                    const domain = email.split('@')[1];
                    return domain && !['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'].includes(domain);
                });

                primaryEmail = businessEmails.length > 0 ? businessEmails[0] : allEmails[0];
                console.log(`   📧 Found ${allEmails.length} emails: ${allEmails.join(', ')}`);
            } else {
                console.log(`   ⚠️ No emails found on website`);
            }
        } else {
            console.log(`   ⚠️ No valid website to scrape`);
        }

        // Only keep results with valid emails
        if (primaryEmail !== 'N/A') {
            const result = {
                name: place.title || 'N/A',
                phone: place.phone || 'N/A',
                email: primaryEmail,
                website: place.website || 'N/A',
                rating: place.rating || 0,
                reviews: place.reviews || 0,
                keyword: keywords,
                keywordCity: workflowContext.keywordCity || '',
                keywordIndustry: workflowContext.keywordIndustry || '',
                keywordIntent: workflowContext.keywordIntent || '',
                keywordCategory: workflowContext.keywordCategory || '',
                country: workflowContext.country || '',
                countryCode: workflowContext.countryCode || '',
                locale: workflowContext.locale || '',
                language: workflowContext.language || '',
                executionId: workflowContext.executionId || '',
                timestamp: new Date().toISOString()
            };

            validResults.push(result);
            console.log(`   ✅ KEPT - Email: ${primaryEmail}`);
        } else {
            console.log(`   ❌ SKIPPED - No valid email found`);
        }

        // Delay between requests
        if (i < places.length - 1) {
            await new Promise(resolve => setTimeout(resolve, config.delayBetweenRequests));
        }
    }

    // Print summary
    console.log(`\n📊 Summary:`);
    console.log(`   Total processed: ${processedCount}`);
    console.log(`   Valid results with emails: ${validResults.length}`);
    console.log(`   Skipped: ${processedCount - validResults.length}`);

    // -------- RETURN RESULTS --------

    if (validResults.length > 0) {
        return validResults.map(result => ({
            json: result
        }));
    }

    // Fallback response when no results found
    return [{
        json: {
            message: 'No businesses with valid email addresses found',
            searchKeywords: keywords,
            keyword: keywords,
            keywordCity: workflowContext.keywordCity || '',
            keywordIndustry: workflowContext.keywordIndustry || '',
            keywordIntent: workflowContext.keywordIntent || '',
            keywordCategory: workflowContext.keywordCategory || '',
            country: workflowContext.country || '',
            countryCode: workflowContext.countryCode || '',
            locale: workflowContext.locale || '',
            language: workflowContext.language || '',
            executionId: workflowContext.executionId || '',
            totalProcessed: processedCount,
            success: true,
            timestamp: new Date().toISOString()
        }
    }];
}

// Execute the workflow
return await main();

const cfg = $('Runtime Config').first().json;
const validation = cfg.emailValidation || {};
const data = $getWorkflowStaticData('global');
data.invalidEmails ||= {};
data.domainMxCache ||= {};

const disposableDomains = new Set([
  'mailinator.com','10minutemail.com','guerrillamail.com','tempmail.com','yopmail.com','trashmail.com'
]);
const blockedDomains = new Set([...(validation.blockedDomains || []), ...disposableDomains].map(d => String(d).toLowerCase()));
const blockedLocalParts = new Set((validation.blockedLocalParts || []).map(v => String(v).toLowerCase()));
const provider = validation.dnsProvider || 'https://dns.google/resolve';
const timeout = validation.timeoutMs || 8000;

function syntax(email) {
  if (!email || typeof email !== 'string') return false;
  if (email.length > 254) return false;
  const parts = email.split('@');
  if (parts.length !== 2) return false;
  const [local, domain] = parts;
  if (!local || !domain || local.length > 64) return false;
  if (local.startsWith('.') || local.endsWith('.') || local.includes('..')) return false;
  if (!/^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+$/i.test(local)) return false;
  if (!/^(?!-)(?:[a-z0-9-]{1,63}\.)+[a-z]{2,63}$/i.test(domain)) return false;
  return true;
}
function getDomain(email) { return String(email).toLowerCase().split('@')[1] || ''; }
function getLocal(email) { return String(email).toLowerCase().split('@')[0] || ''; }
async function lookupMx(domain) {
  const cached = data.domainMxCache[domain];
  if (cached && Date.now() - new Date(cached.checkedAt).getTime() < 7 * 86400000) return cached;
  let result = {domain, checkedAt: new Date().toISOString(), hasMx: false, mxRecords: [], reason: 'mx_lookup_failed'};
  try {
    const res = await this.helpers.httpRequest({method:'GET',url:provider,qs:{name:domain,type:'MX'},json:true,timeout});
    const records = (res.Answer || []).filter(a => Number(a.type) === 15).map(a => String(a.data || '').trim()).filter(Boolean);
    result = {domain, checkedAt: new Date().toISOString(), hasMx: records.length > 0, mxRecords: records, reason: records.length ? 'mx_found' : 'no_mx_records'};
  } catch (e) {
    result.reason = `mx_lookup_error: ${e.message}`;
  }
  data.domainMxCache[domain] = result;
  return result;
}

const out = [];
for (const item of items) {
  const j = item.json;
  const email = String(j.email || '').trim().toLowerCase();
  const domain = getDomain(email);
  const local = getLocal(email);
  let status = 'valid';
  let reason = 'syntax_and_mx_valid';
  let mx = {hasMx: true, mxRecords: []};

  if (data.invalidEmails[email]) {
    status = 'invalid'; reason = data.invalidEmails[email].reason || 'previously_bounced_or_invalid';
  } else if (!syntax(email)) {
    status = 'invalid'; reason = 'invalid_email_syntax';
  } else if (blockedDomains.has(domain)) {
    status = 'invalid'; reason = 'blocked_or_disposable_domain';
  } else if (blockedLocalParts.has(local)) {
    status = 'invalid'; reason = 'blocked_role_or_no_reply_local_part';
  } else if (validation.enabled !== false && validation.requireMx !== false) {
    mx = await lookupMx.call(this, domain);
    if (!mx.hasMx) { status = 'invalid'; reason = mx.reason || 'no_mx_records'; }
  }

  if (status === 'valid') {
    out.push({json:{...j,emailValidationStatus:status,emailValidationReason:reason,emailMxRecords:(mx.mxRecords || []).join(' | '),emailMxCheckedAt:mx.checkedAt || new Date().toISOString()}});
  } else {
    data.invalidEmails[email] = {email, domain, reason, checkedAt: new Date().toISOString(), businessName: j.businessName || ''};
  }
}
return out;

